<script setup lang="ts">
type Correction={id:string;source:string;replacement:string;status:'PENDING'|'ACCEPTED'|'REJECTED'};
defineProps<{corrections:Correction[];busy?:boolean}>();
const emit=defineEmits<{decision:[id:string,decision:'accept'|'reject'];undo:[id:string]}>();
</script>
<template><aside class="correction-panel" aria-label="纠错处理"><header><strong>纠错</strong><span class="muted">待处理 {{corrections.filter(c=>c.status==='PENDING').length}}</span></header><p v-if="!corrections.length" class="muted">暂无纠错记录</p><ul v-else><li v-for="correction in corrections" :key="correction.id"><div><del>{{correction.source}}</del><span>→</span><b>{{correction.replacement}}</b></div><small>{{correction.status==='PENDING'?'待处理':correction.status==='ACCEPTED'?'已接受':'已拒绝'}}</small><div v-if="correction.status==='PENDING'" class="actions"><button type="button" class="btn sm" :disabled="busy" @click="emit('decision',correction.id,'reject')">拒绝</button><button type="button" class="btn sm primary" :disabled="busy" @click="emit('decision',correction.id,'accept')">接受</button></div><button v-else-if="correction.status==='ACCEPTED'" type="button" class="btn sm ghost" :disabled="busy" @click="emit('undo',correction.id)">撤销</button></li></ul></aside></template>
<style scoped>.correction-panel{padding:16px;border:1px solid var(--border);border-radius:8px;background:#fff}.correction-panel header{display:flex;justify-content:space-between}.muted,.correction-panel small{color:var(--muted);font-size:12px}.correction-panel ul{list-style:none;padding:0;margin:12px 0}.correction-panel li{padding:10px 0;border-bottom:1px solid var(--border)}.correction-panel li>div:first-child{display:flex;gap:8px;overflow-wrap:anywhere}.actions{display:flex;gap:6px;margin-top:8px}.correction-panel button{cursor:pointer}</style>
